adcs_vec3_t t_realized = adcs_vec3_cross(&realized_dipole, field);

// Compute lost torque: ||T_ideal - T_realized||
adcs_vec3_t diff = adcs_vec3_sub(&t_ideal, &t_realized);
double loss = adcs_vec3_norm(&diff);

// Assign outputs
*realized = realized_dipole;
*torque = t_ideal;
*lost_torque = loss;
*mask = sat_mask;

return ADCS_OK;
